"Mit Google ist nichts einzutragen: TW-CAD nimmt automatisch den Schlüssel aus der Master-App (gleicher Browser). Abgerechnet wird über dein Google-Konto.": "Z Google nie trzeba nic wpisywać: TW-CAD automatycznie używa klucza z aplikacji Master (ta sama przeglądarka). Rozliczenie przez Twoje konto Google.",
"z. B.: Bad 2,80 × 2,20 m Innenmaß, Wände 11,5 cm, Tür 88,5 unten links mit 15 cm Abstand, Fenster 101 rechts mittig BRH 1,50, Boden 60×30 Drittelverband, Wand 30×60 bis 2,10 m": "np.: Łazienka 2,80 × 2,20 m wymiar wewnętrzny, ściany 11,5 cm, drzwi 88,5 na dole po lewej 15 cm od narożnika, okno 101 po prawej na środku, parapet 1,50, podłoga 60×30 przesunięcie o 1/3, ściana 30×60 do 2,10 m",
"Zeichnen per Text": "Rysowanie tekstem",
"Plan ändern per Sprache oder Text": "Zmiana planu głosem lub tekstem",
"Sag einfach, was geändert werden soll: „Fenster im Bad 1,01 breiter“, „Wand zwischen Küche und Flur 2 cm dicker“, „WC im Gäste-WC an die Nordwand“, „Boden im Flur 60 × 60 Kreuzfuge“ oder frag „wie groß ist das Bad?“. Mit Mikrofon-Knopf auch gesprochen. Kurzbefehl überall: Strg+K.": "Po prostu powiedz, co zmienić: „okno w łazience szersze o 1,01”, „ściana między kuchnią a korytarzem grubsza o 2 cm”, „WC w toalecie dla gości do ściany północnej”, „podłoga w korytarzu 60 × 60 fuga krzyżowa” lub zapytaj „jak duża jest łazienka?”. Przyciskiem mikrofonu także głosem. Skrót wszędzie: Ctrl+K.",
"Grundriss aus Raumprogramm entwerfen": "Zaprojektuj rzut z programu pomieszczeń",
"Raumprogramm beschreiben (Räume, Größen, Geschosse, Grundstück) – die KI entwirft einen DIN-gerechten Grundriss und TW-CAD baut ihn als neues Projekt mit Wänden, Räumen, Türen, Fenstern, Treppe und Dach auf.": "Opisz program pomieszczeń (pomieszczenia, wielkości, kondygnacje, działka) – AI zaprojektuje rzut zgodny z DIN, a TW-CAD utworzy z niego nowy projekt ze ścianami, pomieszczeniami, drzwiami, oknami, schodami i dachem.",
"Visualisierung": "Wizualizacja",
"In „3D & Fassade“ (oder „Raum von innen“) rechts unter Export: „KI-Visualisierung“ – die KI schreibt aus dem 3D-Bild fertige Prompts für Bild-KIs (ChatGPT, Firefly, Midjourney) plus Referenzbild und Kundentext.": "W „3D i elewacja” (lub „Pomieszczenie od środka”) po prawej w sekcji Eksport: „Wizualizacja AI” – AI pisze z obrazu 3D gotowe prompty dla AI graficznych (ChatGPT, Firefly, Midjourney) oraz obraz referencyjny i tekst dla klienta.",
"Leistungsverzeichnis auswerten": "Analizuj przedmiar robót",
"LV als PDF, GAEB (X83/D83) oder Text: die KI findet alle Fliesenpositionen mit Hersteller, Serie, Format, Farbe und Fuge und legt sie in der Fliesen-Bibliothek dieses Projekts an. Danach im Fliesenplan „Aus LV/Bibliothek“.": "Przedmiar jako PDF, GAEB (X83/D83) lub tekst: AI znajduje wszystkie pozycje płytek z producentem, serią, formatem, kolorem i fugą i dodaje je do biblioteki płytek tego projektu. Następnie w planie płytek „Z przedmiaru/biblioteki”.",
