"Noch keine Fliesen aus einem Leistungsverzeichnis. Kopiere den LV-Text (aus PDF oder GAEB als Text) über „LV-Text einfügen“ hinein – Positionen mit Format, Hersteller, Farbe, Rutschhemmung und Bereich (Boden/Wand/Sockel) werden erkannt.": "Brak płytek z przedmiaru. Wklej tekst przedmiaru (z PDF lub GAEB jako tekst) przez „Wklej tekst przedmiaru” – rozpoznane zostaną pozycje z formatem, producentem, kolorem, antypoślizgowością i obszarem (podłoga/ściana/cokół).",
"Noch keine Fliesen aus dem LV. Wege: LV-Datei (PDF/GAEB) von der KI lesen lassen, direkt aus dem Baustellen-Ordner holen oder den LV-Text hineinkopieren – die Fliesenpositionen mit Format, Hersteller, Farbe, Rutschhemmung und Bereich (Boden/Wand/Sockel) werden erkannt.": "Brak płytek z przedmiaru. Sposoby: niech AI odczyta plik przedmiaru (PDF/GAEB), pobierz go z folderu budowy lub wklej tekst – pozycje płytek z formatem, producentem, kolorem, antypoślizgowością i obszarem (podłoga/ściana/cokół) zostaną rozpoznane.",
