"Treppe passt nicht in „{0}“ ({1} × {2} m) – bitte mit dem Treppen-Werkzeug einsetzen (z. B. gewendelt).": "Schody nie mieszczą się w „{0}” ({1} × {2} m) – wstaw je narzędziem Schody (np. zabiegowe).",
"z. B.: Einfamilienhaus für 4 Personen, ca. 140 m² Wohnfläche, 2 Geschosse mit Satteldach 38°.\nEG: Diele mit Garderobe, Gäste-WC, Küche offen zu Essen/Wohnen ca. 40 m² nach Süden, Hauswirtschaftsraum, Arbeitszimmer 10 m².\nOG: Eltern 15 m² mit Ankleide, 2 Kinderzimmer je 12 m², Bad 10 m² mit bodengleicher Dusche und Wanne, Abstellraum.\nGrundstück: Haus max. 11 × 9 m, Zufahrt von Westen.": "np.: dom jednorodzinny dla 4 osób, ok. 140 m² powierzchni mieszkalnej, 2 kondygnacje z dachem dwuspadowym 38°.\nParter: przedpokój z garderobą, WC dla gości, kuchnia otwarta na jadalnię/salon ok. 40 m² od południa, pomieszczenie gospodarcze, gabinet 10 m².\nPiętro: rodzice 15 m² z garderobą, 2 pokoje dzieci po 12 m², łazienka 10 m² z prysznicem bez brodzika i wanną, schowek.\nDziałka: dom maks. 11 × 9 m, wjazd od zachodu.",
"Die KI entwirft einen Grundriss als Vorschlag (Achsmaße, Raster 12,5 cm) und TW-CAD baut ihn als neues Projekt mit Wänden, Räumen, Türen, Fenstern, Treppe und Dach auf. Danach normal weiterbearbeiten – nichts im aktuellen Projekt wird überschrieben.": "AI projektuje rzut jako propozycję (wymiary osiowe, siatka 12,5 cm), a TW-CAD buduje z niego nowy projekt ze ścianami, pomieszczeniami, drzwiami, oknami, schodami i dachem. Potem edytuj normalnie – nic w bieżącym projekcie nie zostanie nadpisane.",
