"Flächen sind Netto-Raumflächen aus dem Modell (Innenmaß der Wände, ohne Putzabzug). Wohnfläche nach Wohnflächenverordnung (WoFlV): Raumteile ab 2 m lichter Höhe voll, 1–2 m zur Hälfte, unter 1 m nicht; Balkone/Terrassen in der Regel zu einem Viertel; Keller, Heizungsräume und Garagen zählen nicht zur Wohnfläche. BGF = Brutto-Grundfläche (Außenmaß), KGF = BGF − NRF, BRI ≈ BGF × Geschosshöhe.": "Powierzchnie to powierzchnie netto pomieszczeń z modelu (wymiar wewnętrzny ścian, bez odliczenia tynku). Powierzchnia mieszkalna wg niemieckiego rozporządzenia WoFlV: części pomieszczeń o wysokości w świetle od 2 m w całości, 1–2 m w połowie, poniżej 1 m wcale; balkony/tarasy zwykle w jednej czwartej; piwnice, kotłownie i garaże nie wliczają się do powierzchni mieszkalnej. BGF = powierzchnia całkowita brutto (wymiar zewnętrzny), KGF = powierzchnia konstrukcji = BGF − NRF (powierzchnia netto), BRI ≈ BGF × wysokość kondygnacji (kubatura brutto).",
