"Nutzung wird aus dem Raumnamen vorgeschlagen (Bad → NUF 7, Flur → VF, Heizung → TF …) und lässt sich je Raum ändern. Dachschrägen werden aus dem Dach berechnet: Wohnfläche ≥ 2 m voll, 1–2 m halb, unter 1 m nicht (§ 4 WoFlV).": "Użytkowanie jest proponowane z nazwy pomieszczenia (Łazienka → NUF 7, Korytarz → VF, Kotłownia → TF …) i można je zmienić dla każdego pomieszczenia. Skosy są liczone z dachu: pow. mieszkalna ≥ 2 m w całości, 1–2 m w połowie, poniżej 1 m wcale (§ 4 WoFlV).",
