"KI-Erläuterung": "Wyjaśnienie AI",
"Raumhöhen, Belichtung, Türen, Treppen (DIN 18065), Absturzsicherung, Bewegungsflächen (DIN 18040-2) – Zeile anklicken = im Plan zeigen": "Wysokości pomieszczeń, oświetlenie, drzwi, schody (DIN 18065), zabezpieczenie przed upadkiem, powierzchnie manewrowe (DIN 18040-2) – kliknij wiersz = pokaż na planie",
