"Barrierefreiheit ": "Dostępność ",
"🤖 KI-Erläuterung": "🤖 Wyjaśnienie AI",
"schließen": "zamknij",
"Keine Einträge in dieser Auswahl.": "Brak wpisów w tym wyborze.",
"Noch nichts zu prüfen – zeichne Wände, Räume, Türen und Fenster.": "Na razie nie ma czego sprawdzać – narysuj ściany, pomieszczenia, drzwi i okna.",
"Vereinfachte Prüfung aus dem Modell nach {0}, DIN 18065 und DIN 18040-2. Sie ersetzt keine bauaufsichtliche Prüfung; im Zweifel gilt der Normtext bzw. die Landesbauordnung. Räume ohne Aufenthalt (Bad, Flur, Abstellraum …) werden bei Raumhöhe und Belichtung nicht geprüft – die Nutzung stellst du im Raumbuch ein.": "Uproszczona kontrola z modelu wg {0}, DIN 18065 (schody) i DIN 18040-2 (mieszkania bez barier). Nie zastępuje urzędowej kontroli; w razie wątpliwości obowiązuje tekst normy lub krajowe prawo budowlane. Pomieszczenia nieprzeznaczone na pobyt ludzi (łazienka, korytarz, schowek …) nie są sprawdzane pod kątem wysokości i oświetlenia – użytkowanie ustawisz w zestawieniu pomieszczeń.",
"Erst KI einrichten (Stern-Knopf oben) – dann erklärt sie die Prüfung.": "Najpierw skonfiguruj AI (przycisk z gwiazdką u góry) – wtedy wyjaśni kontrolę.",
"Alles erfüllt – die Prüfung hat keine Fehler oder Hinweise gefunden. 👍": "Wszystko spełnione – kontrola nie znalazła błędów ani uwag. 👍",
